package it.project.fly;

import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * The fly's "spinal cord".
 *
 * In a real fly the walking rhythm is generated by the ventral nerve cord (VNC),
 * which is not part of the FlyWire connectome. Here we stand in for it:
 *
 *  - spontaneous walking: alternates pauses and walks, with a steering that
 *    drifts slowly (like a fly exploring)
 *  - odors: when the BRAIN perceives an odor (value 0..1 from the server),
 *    it turns toward the source if the odor is attractive, away if it is aversive.
 *    The stronger the brain perceives it, the more the odor takes over.
 *  - players: a player's odor is neither good nor bad at birth. It becomes so
 *    through experience: the valence comes from the mushroom-body memory (server).
 *
 * Escape does NOT go through here: it is decided entirely by the brain.
 */
public final class Spinal {

    /** An odor source as seen by the fly: angle in degrees (+ = left), distance. */
    public record Source(String odor, double angle, double dist) {}

    /**
     * Command for the body: forward (0..1) and steering (-1..1, + = left).
     * mode is an internal English key (idle, wandering, following_odor, avoiding_odor,
     * following_player, avoiding_player), translated for players via Lang (mode.*);
     * odor is the odor the mode refers to (following_odor / avoiding_odor), otherwise null.
     */
    public record Drive(double fwd, double turn, String mode, String odor) {}

    private static final double ARRIVED = 1.2;       // blocks: "I have reached the fruit"
    private static final double TURN_GAIN = 45.0;    // degrees of error for full steering

    private final Settings cfg;
    private final Random rng = new Random();

    private boolean walking;
    private int phaseTicks;
    private double wanderTurn;

    public Spinal(Settings cfg) {
        this.cfg = cfg;
    }

    public Drive step(Map<String, Double> perceive, List<Source> sources, boolean blocked, double playerValence) {
        // --- spontaneous walking -------------------------------------------
        if (--phaseTicks <= 0) {
            walking = rng.nextDouble() < cfg.activity();
            phaseTicks = 40 + rng.nextInt(100);       // 2..7 seconds
        }
        wanderTurn += -0.05 * wanderTurn + rng.nextGaussian() * 0.08;
        wanderTurn = clamp(wanderTurn, -1, 1);
        double wFwd = walking ? cfg.wanderSpeed() : 0.0;
        double wTurn = walking ? wanderTurn : wanderTurn * 0.3;   // when standing still it looks around

        // --- odors: the strongest among those the brain perceives ------------
        double best = 0, oFwd = 0, oTurn = 0;
        String bestOdor = null;
        if (perceive != null) {
            for (Map.Entry<String, Double> e : perceive.entrySet()) {
                double v = cfg.valence().getOrDefault(e.getKey(), 0.0);
                double strength = e.getValue() * Math.abs(v);
                if (strength < 0.05 || strength <= best) continue;
                Source src = nearest(sources, e.getKey());
                if (src == null) continue;

                best = strength;
                bestOdor = e.getKey();
                if (v > 0) {                          // attractive: head toward it
                    oTurn = clamp(src.angle() / TURN_GAIN, -1, 1);
                    oFwd = src.dist() > ARRIVED ? 1.0 - 0.5 * Math.abs(oTurn) : 0.0;
                } else {                              // aversive: head the opposite way
                    double away = src.angle() > 0 ? src.angle() - 180 : src.angle() + 180;
                    oTurn = clamp(away / TURN_GAIN, -1, 1);
                    oFwd = 1.0 - 0.5 * Math.abs(oTurn);
                }
            }
        }

        // --- players: good or bad according to memory --------------------------
        boolean player = false;
        double pv = Math.abs(playerValence);
        if (pv >= cfg.memoryMin()) {
            double strength = Math.min(1.0, pv * 2.5);
            Source src = nearest(sources, "player");
            if (src != null && strength > best) {
                best = strength;
                bestOdor = "player";
                player = true;
                if (playerValence > 0) {              // knows and likes you: comes close
                    oTurn = clamp(src.angle() / TURN_GAIN, -1, 1);
                    oFwd = src.dist() > cfg.keepDistance() ? 1.0 - 0.5 * Math.abs(oTurn) : 0.0;
                } else {                              // remembers you hurt it: away
                    double away = src.angle() > 0 ? src.angle() - 180 : src.angle() + 180;
                    oTurn = clamp(away / TURN_GAIN, -1, 1);
                    oFwd = 1.0 - 0.5 * Math.abs(oTurn);
                }
            }
        }

        // --- blend: the stronger the odor, the more it is in charge ----------
        double w = clamp(best * 1.5, 0, 1);
        double fwd = wFwd * (1 - w) + oFwd * w;
        double turn = wTurn * (1 - w) + oTurn * w;
        String mode = bestOdor == null ? (walking ? "wandering" : "idle")
                : player ? (playerValence > 0 ? "following_player" : "avoiding_player")
                : (cfg.valence().getOrDefault(bestOdor, 0.0) > 0 ? "following_odor" : "avoiding_odor");
        String odor = bestOdor == null || player ? null : bestOdor;

        if (blocked) {                                // a wall ahead: turn
            turn = wanderTurn >= 0 ? 1.0 : -1.0;
            fwd *= 0.3;
        }
        return new Drive(fwd, turn, mode, odor);
    }

    private static Source nearest(List<Source> sources, String odor) {
        Source best = null;
        for (Source s : sources) {
            if (s.odor().equals(odor) && (best == null || s.dist() < best.dist())) best = s;
        }
        return best;
    }

    private static double clamp(double v, double lo, double hi) {
        return Math.max(lo, Math.min(hi, v));
    }
}
